"""v0.7 additions. Called after the established book-site generator.

Keep the canonical book text, registration form markup and brand assets unchanged.
This module only adds navigational/community/library/practice content to the
complete pages produced from the v0.6 master. Rebuilds are deterministic.
"""
from __future__ import annotations
import json
from pathlib import Path


def replace_required(content: str, before: str, after: str, label: str) -> str:
    if content.count(before) != 1:
        raise RuntimeError(f'{label}: expected exactly one anchor, got {content.count(before)}')
    return content.replace(before, after, 1)


def write_adjusted(root: Path, path: str, fn) -> None:
    file = root / path
    file.write_text(fn(file.read_text(encoding='utf8')), encoding='utf8')


# Custom vector symbols: deliberately different diagrams, sharing the book's line-art vocabulary.
