def reflect_html(prompts):
    # The weekly selection uses the visitor's local date and a fixed, publicly visible
    # twelve-prompt cycle. It never suggests that new material is automatically authored.
    data=json.dumps(prompts, ensure_ascii=False).replace('<','\\u003c')
    return '''<section class="shell page-hero reflect-hero"><span class="eyebrow">A practice for ordinary life</span><h1>Make room to notice.</h1><p class="lead">The Reflection of Chance is an invitation to look at what happened, what you could influence and what might become possible next. Not a test, a streak, or a demand for certainty.</p><div class="button-line"><a class="btn btn-primary" href="#reflection-workspace">Start a private reflection</a><a class="btn btn-outline" href="#reflection-guides">Get a printable guide</a></div></section>
<section class="shell weekly-practice" aria-labelledby="weekly-heading"><div class="weekly-practice-copy"><span class="eyebrow">A question for this week</span><h2 id="weekly-heading" data-weekly-title>An unexpected opening</h2><p data-weekly-question>What unexpected opportunity appeared in your life recently, however small?</p><p class="weekly-action" data-weekly-action>Name one thing you can do to leave that possibility open for yourself or another person.</p><p class="practice-rotation" data-weekly-period>This prompt is part of a rotating set of twelve questions.</p><div class="button-line"><a href="#reflection-workspace" class="text-link">Reflect on this question →</a><button class="quiet-button" type="button" data-next-weekly>Explore another question</button></div></div><div class="weekly-mark" aria-hidden="true"><svg viewBox="0 0 220 220" fill="none"><circle cx="110" cy="110" r="75" stroke="currentColor" stroke-width="1.2"/><circle cx="110" cy="110" r="34" stroke="#286cb8" stroke-width="1.7"/><path d="M20 109h180M110 20v180M49 49l122 122" stroke="currentColor" stroke-opacity=".3"/><circle cx="110" cy="110" r="5" fill="#286cb8"/></svg></div></section>
<section class="shell section-space reflect-intro"><div class="section-head split"><div><span class="eyebrow">A practice you can make your own</span><h2>Three ways to begin.</h2></div><p>Write a few sentences or take your time. You can keep every word to yourself. A reflection can be useful even if it ends with a question.</p></div><div class="reflection-options"><article><span class="practice-index">01 / Daily</span><h3>The Reflection of Chance</h3><p>Notice circumstances, choice, learning and the future without blaming yourself for what you could not control.</p><button class="text-link" type="button" data-pick-template="chance">Use this practice →</button></article><article><span class="practice-index">02 / Action</span><h3>The Act of Possibility</h3><p>Consider one voluntary way you might help another person or the living world, with consent and within your means.</p><button class="text-link" type="button" data-pick-template="action">Use this practice →</button></article><article><span class="practice-index">03 / Weekly</span><h3>A Week of Possibilities</h3><p>Look across the week for surprises, learning, other people's contributions and something worth carrying forward.</p><button class="text-link" type="button" data-pick-template="week">Use this practice →</button></article></div></section>
<section class="reflect-workspace-wrap" id="reflection-workspace"><div class="shell reflect-workspace-grid"><div class="workspace-context"><span class="eyebrow">Your private space</span><h2>Write without an audience.</h2><p>The prompts below are a way to think, not a form to submit. Your answers stay in this browser tab and are <strong>not sent to H, Formspree or the Fellowship</strong>.</p><p>Nothing is automatically saved. Download a copy before closing the page if you want to keep it. Avoid writing anything sensitive on a shared computer.</p><p class="workspace-note">No score. No perfect streak. No pressure to share.</p><a class="text-link" href="../read/ways-of-reflecting/">Explore reflection in the book →</a></div><div class="workspace-panel"><form id="chance-reflection-form"><label for="reflection-mode">Choose a reflection</label><select id="reflection-mode" name="reflection-mode"><option value="chance">The Reflection of Chance</option><option value="action">The Act of Possibility</option><option value="week">A Week of Possibilities</option></select><div id="reflection-questions"></div><div class="workspace-actions"><button type="button" class="btn btn-primary" id="reflection-download">Download my reflection (.txt)</button><button type="button" class="btn btn-outline" id="reflection-print">Print or save as PDF</button><button type="button" class="quiet-button" id="reflection-clear">Clear answers</button></div><p class="workspace-feedback" id="reflection-status" role="status" aria-live="polite"></p></form></div></div></section>
<section class="shell section-space" id="reflection-guides"><div class="section-head split"><div><span class="eyebrow">Take it offline</span><h2>Keep a reflection beside you.</h2></div><p>Three ready-to-use text templates can be printed, edited or kept privately. They require no login, account, application or internet connection after downloading.</p></div><div class="practice-downloads"><a href="../files/reflection/reflection-of-chance.txt" download><span>01 · A personal practice</span><strong>Reflection of Chance</strong><small>Download the daily guide · TXT ↓</small></a><a href="../files/reflection/act-of-possibility.txt" download><span>02 · A voluntary act</span><strong>Act of Possibility</strong><small>Download the action guide · TXT ↓</small></a><a href="../files/reflection/weekly-review.txt" download><span>03 · A weekly review</span><strong>A Week of Possibilities</strong><small>Download the weekly guide · TXT ↓</small></a></div><div class="prompt-archive"><div><h3>Looking for a different question?</h3><p>Every question in the twelve-week cycle is available here. The featured question changes by calendar week and repeats after twelve weeks; this is a curated library, not a claim that new writing appears automatically.</p></div><details><summary>Browse all twelve questions</summary><ol class="prompt-list">'''+''.join('<li><strong>'+__import__('html').escape(p['title'])+'</strong><span>'+__import__('html').escape(p['question'])+'</span></li>' for p in prompts)+'''</ol></details></div></section>
<section class="shell reflect-end"><span class="eyebrow">The next possibility</span><div><h2>Reflection can lead to action.</h2><p>If a question changes what you notice, consider one small act that might widen another person's options. The Fellowship is developing shared ways to explore these practices, but you do not need to join anything to begin.</p></div><a class="btn btn-outline" href="../focus/">See our current focus</a></section>
<script type="application/json" id="chance-weekly-prompts">'''+data+'''</script>'''


def focus_html(arrow):
    return '''<section class="shell page-hero focus-hero"><span class="eyebrow">What we're building · Updated 22 November 2026</span><h1>A community begins<br>with something real.</h1><p class="lead">Before asking people to donate, join programmes or put their trust in a new institution, we want to demonstrate a simple, useful practice of learning together.</p><div class="button-line"><a class="btn btn-primary" href="#current-focus">See the current goal</a><a class="btn btn-outline" href="../community/#community-interest">Register interest</a></div></section>
<section class="shell focus-primary" id="current-focus"><div><span class="eyebrow">Our current focus · Planning stage</span><h2>Prepare the first online Reflection Circle.</h2><p>An accessible, moderated gathering where adults can discuss one reading from <i>The Book of Chance</i>, try a Reflection of Chance, and exchange perspectives without having to agree on every idea.</p><p>This is a <strong>development goal, not a scheduled event</strong>. We have not announced a date, opened membership or promised mentorship or assistance.</p><div class="button-line"><a class="btn btn-primary" href="../reflect/">Try the reflection practice</a><a class="text-link" href="../community/#community-interest">Hear when activities open →</a></div></div><aside><span class="focus-status">Status · In preparation</span><h3>What would make this worthwhile?</h3><ul><li>A clear, respectful discussion format</li><li>Safe moderation and privacy expectations</li><li>Accessible materials available to everyone</li><li>Participant feedback used to improve the next gathering</li></ul><p>These are intended success measures, not results already achieved.</p></aside></section>
<section class="shell section-space"><div class="section-head split"><div><span class="eyebrow">An honest roadmap</span><h2>Build trust through small commitments.</h2></div><p>These stages describe our direction. They are not launch dates, performance metrics or guarantees.</p></div><div class="focus-roadmap"><article><span>NOW · AVAILABLE</span><h3>Make the foundations public.</h3><p>The complete book is available to read and download. The interest lists and private reflection tools make it possible to begin without formal membership.</p><a class="text-link" href="../downloads/">Explore the library →</a></article><article><span>NEXT · IN PREPARATION</span><h3>Design a first gathering.</h3><p>Publish a format, moderation expectations, access needs and dates only when appropriate arrangements are in place.</p></article><article><span>LATER · PROPOSED</span><h3>Learn, report and improve.</h3><p>Invite voluntary feedback, publish a plain-language account of what was learned, then decide whether and how to expand.</p></article></div></section>
<section class="focus-support"><div class="shell focus-support-inner"><span class="eyebrow">Voluntary support, when we're ready</span><h2>Fund an outcome, not a promise.</h2><p>Our longer-term aim is to keep foundational literature and ordinary Fellowship membership free, while allowing people to support agreed projects if they choose. Contribution can also mean sharing a skill, helping organise a gathering, or making an introduction with consent.</p><div class="focus-support-grid"><article><span>01</span><h3>Publish the goal</h3><p>Describe what we intend to deliver, who benefits, expected costs and decision-making responsibility.</p></article><article><span>02</span><h3>Protect the contribution</h3><p>Establish appropriate legal and financial arrangements, oversight and treatment of purpose-restricted funds before collecting money.</p></article><article><span>03</span><h3>Report the outcome</h3><p>Publish the actual result and spending, including what changed and how unused funds are handled.</p></article></div><p class="focus-disclaimer"><strong>No donations are being accepted through this website at present.</strong> There is no active fundraising target or verified amount raised to display. The Fellowship does not claim to be a registered charity or offer tax-deductible donations.</p></div></section>
<section class="shell section-space"><div class="section-head split"><div><span class="eyebrow">A possible future initiative</span><h2>Chance Campaigns.</h2></div><p>There is a poetic idea worth exploring: letting chance help decide which worthy external cause receives the attention of a future community campaign.</p></div><div class="chance-framework"><div class="chance-wheel-drawing" aria-hidden="true"><svg viewBox="0 0 240 240" fill="none"><circle cx="120" cy="120" r="90" stroke="currentColor" stroke-width="1.5"/><circle cx="120" cy="120" r="47" stroke="#286cb8" stroke-width="1.6"/><path d="M120 30v180M30 120h180M57 57l126 126M183 57 57 183" stroke="currentColor" stroke-width="1.2"/><circle cx="120" cy="120" r="6" fill="#286cb8"/></svg><span>Concept only · No selection in progress</span></div><div><h3>Responsibility before randomness.</h3><p>A future campaign could shortlist independently vetted external charities working on agreed causes. After eligibility and any donor restrictions are established, a publicly documented random draw could choose among genuinely comparable options.</p><p>We would publish the selection method, eligible candidates, campaign purpose and later outcome. Urgent needs should not be forced into a game of chance. Internal member assistance, if ever developed, would use safeguards and needs-based decisions rather than a random wheel.</p><p><strong>Nothing is open for nominations, voting or funding yet.</strong> We will announce any real campaign only after its rules and safeguards are approved.</p></div></div></section>
<section class="shell focus-last"><div><span class="eyebrow">Three useful things today</span><h2>Begin without waiting for a launch.</h2><p>Read a passage, try a reflection, or register to hear when the first community activities are ready. None requires a contribution.</p></div><div class="button-line"><a class="btn btn-outline" href="../read/">Read the book</a><a class="btn btn-outline" href="../reflect/">Reflect privately</a><a class="btn btn-primary" href="../community/#community-interest">Register interest</a></div></section>'''


def apply_v07(root: Path, document, arrow: str, manifest: dict) -> None:
    prompts=json.loads((root/'source/reflection-prompts.json').read_text(encoding='utf8'))
    assert len(prompts)==12 and all(set(p)=={'title','question','practice'} for p in prompts)
    (root/'reflect').mkdir(exist_ok=True)
    (root/'focus').mkdir(exist_ok=True)
    page=document('Reflect · A private practice',reflect_html(prompts),base='../',active='reflect',desc='Try the Reflection of Chance online, explore a rotating weekly question and download free private reflection worksheets.')
    page=page.replace('</body>','<script defer src="../assets/reflect.js?v=0.7"></script></body>')
    (root/'reflect/index.html').write_text(page,encoding='utf8')
    (root/'focus/index.html').write_text(document('Current focus',focus_html(arrow),base='../',active='focus',desc='See the Fellowship of Chance current development goal, honest roadmap, and proposed voluntary funding and future Chance Campaigns.'),encoding='utf8')

    # Introductory action on Fellowship page: first link is a real registration anchor.
    def edit_community(s):
        s=replace_required(s, 'href="#why-participate">Discover what could happen','href="#community-interest">Register interest', 'Fellowship primary CTA')
        s=replace_required(s, 'href="#community-interest">Hear when we open','href="#why-participate">Explore the idea', 'Fellowship secondary CTA')
        for source,new in [('↗',MENTOR_SVG),('⌁',COLLAB_SVG),('◌',SUPPORT_SVG)]:
            s=replace_required(s,'<span class="work-icon">'+source+'</span>','<span class="work-icon work-icon-art">'+new+'</span>', 'programme icon '+source)
        intro='''<section class="shell community-practice-bar"><div><span class="eyebrow">Start before membership opens</span><h2>Take an idea into everyday life.</h2><p>Try a private Reflection of Chance, then see what the Fellowship is preparing next. No account, donation or public disclosure is needed.</p></div><div class="button-line"><a class="btn btn-outline" href="../reflect/">Explore reflections</a><a class="btn btn-outline" href="../focus/">Our current focus</a></div></section>'''
        s=replace_required(s,'<section class="community-support"',intro+'<section class="community-support"','community activity insertion')
        return s
    write_adjusted(root,'community/index.html',edit_community)

    # Give both new pages visibility on the homepage without competing with the book itself.
    homeinsert='''<section class="shell home-practice section-space"><div class="section-head split"><div><span class="eyebrow">More than a book</span><h2>Something to return to.</h2></div><p>A small practice for yourself, and a shared project to watch as the Fellowship takes shape.</p></div><div class="home-practice-grid"><a class="home-practice-card" href="reflect/"><span class="card-overline">REFLECTION OF THE WEEK</span><h3>A few minutes to notice.</h3><p>Explore a rotating weekly question, try a private reflection and take home a printable worksheet.</p><span class="text-link">Open the reflection space →</span></a><a class="home-practice-card" href="focus/"><span class="card-overline">CURRENT FOCUS · PLANNING</span><h3>Prepare the first Reflection Circle.</h3><p>See the next concrete goal, what needs to happen before it begins and how to take part when it's ready.</p><span class="text-link">See what we're building →</span></a></div></section>'''
    def edit_home(s):
        s=replace_required(s,'<section class="shell home-community">',homeinsert+'<section class="shell home-community">','home practices')
        s=replace_required(s,'Interested readers will be able to register when the interest list opens; no money is being collected at this stage.','Interested readers can register for printing updates now; no money is being collected at this stage.','home print availability')
        return s
    write_adjusted(root,'index.html',edit_home)

    # Keep downloadable book editions as the library's feature; add actual resources ahead of aspirational cards.
    shelf='''<section class="shell library-resources" id="practice-guides"><div class="section-head split"><div><span class="eyebrow">Available now · Personal practice</span><h2>Ideas you can actually use.</h2></div><p>Three concise guides translate the book's questions into small private practices. No account, payment or commitment is needed.</p></div><div class="library-resource-grid"><article><span>01 / Reflection</span><h3>The Reflection of Chance</h3><p>Look at what happened, what you could influence and what may be possible next.</p><a class="text-link" href="../files/reflection/reflection-of-chance.txt" download>Download the template ↓</a></article><article><span>02 / Action</span><h3>The Act of Possibility</h3><p>Plan one voluntary action that could widen someone's options while respecting their wishes.</p><a class="text-link" href="../files/reflection/act-of-possibility.txt" download>Download the template ↓</a></article><article><span>03 / Weekly</span><h3>A Week of Possibilities</h3><p>Notice surprise, learning, gratitude and a modest intention for the week ahead.</p><a class="text-link" href="../files/reflection/weekly-review.txt" download>Download the template ↓</a></article></div><div class="library-tool-link"><p>Prefer to write on screen? The interactive reflection workspace works without an account and doesn't submit your writing.</p><a class="btn btn-outline" href="../reflect/">Open the reflection workspace</a></div></section>'''
    write_adjusted(root,'downloads/index.html',lambda s: replace_required(s,'<section class="library-upcoming">',shelf+'<section class="library-upcoming">','library resource shelf'))

    # The local-only reflection editor has a materially different data flow from the two registered interest forms.
    write_adjusted(root,'privacy/index.html',lambda s: replace_required(s,'<h2>What is not collected</h2>', '<h2>The private reflection workspace</h2><p>The optional reflection editor on this website runs in your browser. Reflections are not submitted to Formspree, the Fellowship or the website, and are not automatically saved to your device. You can choose to download or print your own writing. Closing the page without saving will lose it. On a shared computer, avoid entering private information you would not want another user to see.</p>\n<h2>What is not collected</h2>','reflection privacy note'))

    # Index only real public pages, not future programme announcements or scripts.
    from xml.sax.saxutils import escape as xml_escape
    pages=sorted(root.rglob('index.html'))
    base_url='https://thebookofchance.github.io/'
    urls=[]
    for f in pages:
        rel=f.parent.relative_to(root).as_posix()
        path='' if rel=='.' else rel+'/'
        urls.append('  <url><loc>'+xml_escape(base_url+path)+'</loc></url>')
    (root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+'\n'.join(urls)+'\n</urlset>\n',encoding='utf8')
    (root/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://thebookofchance.github.io/sitemap.xml\n',encoding='utf8')

    manifest.update({
        'website_version':'0.7', 'new_pages':['reflect/','focus/'], 'rotation':'twelve curated weekly prompts, repeating',
        'local_private_reflection_workspace':True,'downloadable_reflection_guides':3,
        'fellowship_donations_enabled':False,'charity_campaign_running':False,
        'form_endpoints':'Not altered; existing deployment settings must be preserved'
    })
